def linear_constraint(constraint_like, variable_names):
    """This is the internal interface implementing
    DesignInfo.linear_constraint, see there for docs."""
    variable_names = list(variable_names)

    # Case 1: Already a LinearConstraint
    if isinstance(constraint_like, LinearConstraint):
        if constraint_like.variable_names != variable_names:
            raise ValueError("variable_names don't match")
        return constraint_like

    # Case 2: Dictionary mapping variable names/indices to values
    if isinstance(constraint_like, Mapping):
        coefs_list = []
        constants_list = []

        for name_or_idx, value in constraint_like.items():
            coef = np.zeros(len(variable_names))

            if isinstance(name_or_idx, int):
                if name_or_idx < 0 or name_or_idx >= len(variable_names):
                    raise ValueError(f"index {name_or_idx} out of bounds")
                coef[name_or_idx] = 1
            else:
                try:
                    idx = variable_names.index(name_or_idx)
                    coef[idx] = 1
                except ValueError:
                    raise ValueError(f"unknown variable name: {name_or_idx}")

            coefs_list.append(coef)
            constants_list.append(float(value))

        return LinearConstraint(variable_names, coefs_list, constants_list)

    # Case 3: String expression
    if isinstance(constraint_like, str):
        tree = parse_constraint(constraint_like, variable_names)
