        isinstance(item, str) for item in constraint_like
    ):
        constraints = [linear_constraint(item, variable_names) for item in constraint_like]
        return LinearConstraint.combine(constraints)

    # Case 5: Tuple of (coefs, constants)
    if isinstance(constraint_like, (list, tuple)) and len(constraint_like) == 2:
        coefs, constants = constraint_like
        return LinearConstraint(variable_names, coefs, constants)
